properties.query:
var dbConn;

try {
    var driver = configurationMap.get('db.driver');
    var url = configurationMap.get('db.url');
    var user = configurationMap.get('db.user');
    var password = configurationMap.get('db.password');

    dbConn = DatabaseConnectionFactory.createDatabaseConnection(driver, url, user, password);
    var sql = ` INSERT INTO oh_patient (PAT_FNAME, PAT_SNAME, PAT_NAME, PAT_BDATE, PAT_AGE, PAT_AGETYPE, PAT_SEX, PAT_ADDR, PAT_CITY, PAT_NEXT_KIN, PAT_TELE, PAT_MOTH_NAME, PAT_MOTH, PAT_FATH_NAME, PAT_FATH, PAT_LEDU, PAT_ESTA, PAT_PTOGE, PAT_NOTE, PAT_DELETED, PAT_LOCK, PAT_BTYPE, PAT_TAXCODE, PAT_TIMESTAMP, PAT_CREATED_BY, PAT_CREATED_DATE, PAT_LAST_MODIFIED_BY, PAT_LAST_MODIFIED_DATE, PAT_ACTIVE, PAT_PROFESSION, PAT_MAR_STAT, PAT_PROFILE_PHOTO_ID, PAT_ALLERGIES, PAT_ANAMNESIS) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ? )`;

    var params = [
        $('PAT_FNAME'), $('PAT_SNAME'), $('PAT_NAME'), $('PAT_BDATE'), $('PAT_AGE'), $('PAT_AGETYPE'), $('PAT_SEX'), $('PAT_ADDR'), $('PAT_CITY'),
        $('PAT_NEXT_KIN'), $('PAT_TELE'), $('PAT_MOTH_NAME'), $('PAT_MOTH'), $('PAT_FATH_NAME'), $('PAT_FATH'), $('PAT_LEDU'), $('PAT_ESTA'),
        $('PAT_PTOGE'), $('PAT_NOTE'), $('PAT_DELETED'), $('PAT_LOCK'), $('PAT_BTYPE'), $('PAT_TAXCODE'), $('PAT_TIMESTAMP'),
        $('PAT_CREATED_BY'), $('PAT_CREATED_DATE'), $('PAT_LAST_MODIFIED_BY'), $('PAT_LAST_MODIFIED_DATE'),
        $('PAT_ACTIVE'), $('PAT_PROFESSION'), $('PAT_MAR_STAT'), $('PAT_PROFILE_PHOTO_ID'), $('PAT_ALLERGIES'), $('PAT_ANAMNESIS')
    ];

    logger.info("📥 Insertando nuevo paciente...");
    dbConn.executeUpdate(sql, params);
    logger.info("✅ Registro insertado correctamente.");

} catch (e) {
    logger.error("❌ Error al insertar paciente: " + e);
} finally {
    if (dbConn) dbConn.close();
}

