com.mirth.connect.plugins.javascriptrule.script:
//Validación de campos
var validacion_ok = "1";
if (parseInt($('PAT_AGE')) > 300)
{
	validacion_ok="0";
}
channelMap.put('validacion_ok', validacion_ok);
return validacion_ok == "1";

